{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Kernen er rigtig: epikrise eller afslutningsnotat som udgangspunkt ved afsluttet behandling. Svaret tilføjer dog et krav om journal fra egen læge fra de seneste 2-3 år, som ikke findes i kilderne. Det gør også journal fra egen læge til et fast krav ved siden af epikrisen, selvom kilderne kræver journalmateriale fra en af de nævnte behandlertyper. Ordet 'varig' funktionsnedsættelse indgår ikke."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Epikrise eller afslutningsbrev 'som udgangspunkt' ved afsluttet behandling er med. Svaret angiver ikke journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik som minimumskrav. Det nævner kun egen læge og epikrise fra hospital, klinik eller speciallæge. Kravet om, at materialet beskriver den varige funktionsnedsættelse, er heller ikke gengivet. Svaret siger kun 'funktionsnedsættelsen'."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken lægelig dokumentation der skal vedlægges, når behandlingen er afsluttet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til 'SU's dokumentationsside' og 'SU's vejledning' og nævner SU-loven (LBK nr. 395 af 2023) § 54 og § 46 h. Der er altså angivet identificerbare kilder. De centrale påstande er dog markeret '(uden kilde)', så sporbarheden er svag."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "De angivne lovbestemmelser, SU-loven § 54 og § 46 h, findes ikke i de frosne kilder og er ikke anvendelige på dokumentationskravet. Den relevante hjemmel, SU-bekendtgørelsen § 37, stk. 1 og 3, og vejledningens afsnit 4.1 er ikke citeret. Fodnoterne '1' og '2' kan ikke identificeres."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De viste kilder, SU-loven § 54 og § 46 h, understøtter ikke påstandene om dokumentationens indhold. Det gælder 2-3 års journal, diagnose, hverdagspåvirkning og erhvervsevne."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttede krav og tærskler. Det gælder journal fra de sidste 2-3 år, at journal fra egen læge skal vedlægges ved siden af epikrisen, og en liste over, hvad dokumentationen 'mindst bør vise' (diagnose, behandling, erhvervsevne)."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "'Som udgangspunkt' er bevaret for epikrisen, og svaret nævner, at yderligere dokumentation kan være nødvendig, hvis journalerne ikke er tilstrækkelige. Afvisning er gengivet som en mulig følge. At dokumentets titel ikke i sig selv afgør tilstrækkeligheden, siges ikke eksplicit."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: afsluttet behandling giver epikrise plus journal, og kun egen læge giver journal alene. Der er ingen indbyrdes modstrid."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Skal vedlægge ... journal fra egen læge ... 2-3 år' gør en uunderstøttet betingelse til et absolut krav. Samtidig er den obligatoriske afvisning ('afviser Udbetaling Danmark behandling af sagen') afsvækket til 'kan ellers risikere at blive afvist'."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "yes",
      "reason": "Svaret angiver, at epikrise eller afslutningsnotat som udgangspunkt skal vedlægges, når behandlingen er afsluttet."
    },
    "A32": {
      "label": "yes",
      "reason": "Svaret dækker, at dokumentationen som udgangspunkt omfatter epikrise eller afslutningsnotat ved afsluttet behandling. Det formulerer det som et 'skal' og knytter det til en uhjemlet egen-læge-journal, men udgangspunktet er bevaret."
    }
  },
  "overall_notes": "Svaret rammer epikrisepunktet, men tilføjer et uunderstøttet krav om 2-3 års journal og journal fra egen læge i alle tilfælde. Det udelader kravet om journalmateriale fra flere behandlertyper og om den varige funktionsnedsættelse. De viste kilder, SU-loven § 54 og § 46 h, er de forkerte, og de centrale udsagn er markeret '(uden kilde)'. Svaret bør derfor bruges med forbehold."
}

